// Base-game rules. Resource transfers conserve 19 cards of each kind.
export const RES=['wood','brick','sheep','wheat','ore'];
export const LABEL={wood:'木材',brick:'砖块',sheep:'羊毛',wheat:'麦穗',ore:'矿石'};
export const COST={road:{wood:1,brick:1},settlement:{wood:1,brick:1,sheep:1,wheat:1},city:{wheat:2,ore:3},dev:{sheep:1,wheat:1,ore:1}};
export const DEV_NAMES={knight:'骑士',point:'胜利点',roads:'道路建设',plenty:'丰收',monopoly:'垄断'};
export const VERSION=3;
export const emptyResources=()=>Object.fromEntries(RES.map(r=>[r,0]));
export const isSetup=s=>['setup-settlement','setup-road'].includes(s.phase);
export const total=p=>p.resources?RES.reduce((n,r)=>n+(p.resources[r]??0),0):(p.resourceCount??0);
export const canPay=(p,cost)=>Object.entries(cost).every(([r,n])=>(p.resources?.[r]??0)>=n);
export const sumPackage=pack=>RES.reduce((n,r)=>n+(pack?.[r]??0),0);
const fail=message=>({ok:false,message});
const clone=obj=>JSON.parse(JSON.stringify(obj));
export function random(s){let x=s.rng|0;x^=x<<13;x^=x>>>17;x^=x<<5;s.rng=x>>>0;return(x>>>0)/4294967296;}
function shuffle(s,items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random(s)*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function log(s,text,player=s.current,kind='action'){s.logs.unshift({text,player,kind,turn:s.turn,id:s.eventId++});s.logs=s.logs.slice(0,160);}
function pay(s,p,cost){for(const[r,n]of Object.entries(cost)){s.players[p].resources[r]-=n;s.bank[r]+=n;}}
function take(s,p,cards){for(const r of RES){const n=cards[r]??0;s.bank[r]-=n;s.players[p].resources[r]+=n;}}
export function publicPoints(s,p){return s.vertices.filter(v=>v.owner===p).reduce((n,v)=>n+v.level,0)+(s.longestOwner===p?2:0)+(s.largestOwner===p?2:0);}
export function points(s,p){return publicPoints(s,p)+(s.players[p].dev??[]).filter(c=>c.type==='point').length;}
export const countPieces=(s,p,type)=>type==='road'?s.edges.filter(e=>e.owner===p).length:s.vertices.filter(v=>v.owner===p&&v.level===(type==='city'?2:1)).length;
export function adjacent(s,v){return v.edges.map(id=>{const e=s.edges[id];return s.vertices[e.a===v.id?e.b:e.a];});}
export function legalSettlements(s,p,setup=false){if(countPieces(s,p,'settlement')>=5)return[];return s.vertices.filter(v=>v.owner===null&&adjacent(s,v).every(w=>w.owner===null)&&(setup||v.edges.some(id=>s.edges[id].owner===p))).map(v=>v.id);}
export function legalCities(s,p){return countPieces(s,p,'city')>=4?[]:s.vertices.filter(v=>v.owner===p&&v.level===1).map(v=>v.id);}
export function legalRoads(s,p){if(countPieces(s,p,'road')>=15)return[];return s.edges.filter(e=>e.owner===null&&[e.a,e.b].some(id=>{const v=s.vertices[id];return v.owner===p||(v.owner===null&&v.edges.some(eid=>s.edges[eid].owner===p));})).map(e=>e.id);}
export function legalSetupRoads(s,p=s.current){if(s.phase!=='setup-road'||s.current!==p)return[];const v=s.vertices[s.setupVertex];return v?.owner===p?v.edges.filter(id=>s.edges[id].owner===null):[];}
export function longestRoad(s,p){let best=0;function walk(id,used){best=Math.max(best,used.size);const v=s.vertices[id];if(used.size&&v.owner!==null&&v.owner!==p)return;for(const eid of v.edges){const e=s.edges[eid];if(e.owner!==p||used.has(eid))continue;used.add(eid);walk(e.a===id?e.b:e.a,used);used.delete(eid);}}for(const v of s.vertices)if(v.edges.some(id=>s.edges[id].owner===p))walk(v.id,new Set());return best;}
function award(s,key,values,min){const max=Math.max(...values),leaders=values.map((n,i)=>n===max?i:-1).filter(i=>i!==-1),old=s[key];s[key]=max<min?null:leaders.includes(old)?old:leaders.length===1?leaders[0]:null;if(s[key]!==null&&s[key]!==old)log(s,`${s.players[s[key]].name}获得${key==='longestOwner'?'最长道路':'最大骑士团'}，+2 分`,s[key],'award');}
export function updateAwards(s){s.longest=s.players.map(p=>longestRoad(s,p.id));award(s,'longestOwner',s.longest,5);award(s,'largestOwner',s.players.map(p=>p.knights),3);}
function checkWinner(s){if(!isSetup(s)&&points(s,s.current)>=10){s.winner=s.current;s.phase='over';s.offer=null;log(s,`${s.players[s.current].name}达到 ${points(s,s.current)} 分，赢得本场对局`,s.current,'win');return true;}return false;}
function adjacentTiles(a,b){return Math.max(Math.abs(a.q-b.q),Math.abs(a.r-b.r),Math.abs(a.q+a.r-b.q-b.r))===1;}
function assignNumbers(s){const candidates=shuffle(s,s.tiles.filter(t=>t.type!=='desert'));function search(start,picked){if(picked.length===4)return picked;for(let i=start;i<candidates.length;i++){const t=candidates[i];if(picked.some(u=>adjacentTiles(t,u)))continue;const result=search(i+1,[...picked,t]);if(result)return result;}return null;}const redIds=new Set(search(0,[]).map(t=>t.id)),reds=shuffle(s,[6,6,8,8]),others=shuffle(s,[2,3,3,4,4,5,5,9,9,10,10,11,11,12]);for(const t of s.tiles)t.number=t.type==='desert'?null:redIds.has(t.id)?reds.pop():others.pop();}
export function newGame(seed=Date.now(),options={}){
 const playerCount=options.playerCount===3?3:4;
 const s={version:VERSION,rng:(seed>>>0)||234567,seed:seed>>>0,options:{playerCount,combinedTradeBuild:options.combinedTradeBuild!==false},tiles:[],vertices:[],edges:[],ports:[],players:[],bank:Object.fromEntries(RES.map(r=>[r,19])),deck:[],playedCards:[],current:0,startPlayer:0,setupOrder:[],setupIndex:0,setupVertex:null,turn:1,phase:'setup-settlement',returnPhase:null,tradeOpen:true,dice:null,robber:0,winner:null,longestOwner:null,largestOwner:null,longest:Array(playerCount).fill(0),logs:[],eventId:0,production:[],freeRoads:0,playedDev:false,discardRequired:Array(playerCount).fill(0),discardLeft:0,pendingVictims:[],offer:null};
 const types=shuffle(s,['wood','wood','wood','wood','sheep','sheep','sheep','sheep','wheat','wheat','wheat','wheat','brick','brick','brick','ore','ore','ore','desert']),vm=new Map(),em=new Map();
 for(let r=-2;r<=2;r++)for(let q=-2;q<=2;q++){if(Math.abs(q+r)>2)continue;const id=s.tiles.length,type=types[id],x=390+Math.sqrt(3)*64*(q+r/2),y=302+96*r,t={id,q,r,x,y,type,number:null,vertices:[]};if(type==='desert')s.robber=id;
  for(let j=0;j<6;j++){const a=(j*60-30)*Math.PI/180,vx=x+64*Math.cos(a),vy=y+64*Math.sin(a),key=`${Math.round(vx*10)},${Math.round(vy*10)}`;let vid=vm.get(key);if(vid===undefined){vid=s.vertices.length;vm.set(key,vid);s.vertices.push({id:vid,x:vx,y:vy,tiles:[],edges:[],owner:null,level:0});}s.vertices[vid].tiles.push(id);t.vertices.push(vid);}
  for(let j=0;j<6;j++){const a=t.vertices[j],b=t.vertices[(j+1)%6],key=[a,b].sort((c,d)=>c-d).join(',');if(!em.has(key)){const eid=s.edges.length;em.set(key,eid);s.edges.push({id:eid,a,b,owner:null});s.vertices[a].edges.push(eid);s.vertices[b].edges.push(eid);}}s.tiles.push(t);
 }
 assignNumbers(s);
 s.players=[{name:'你',color:'#db5940',letter:'我'},{name:'小满',color:'#438fc4',letter:'满'},{name:'阿屿',color:'#e4dbc1',letter:'屿'},{name:'林野',color:'#e3a23e',letter:'野'}].slice(0,playerCount).map((p,id)=>({...p,id,resources:emptyResources(),dev:[],knights:0}));
 s.deck=shuffle(s,[...Array(14).fill('knight'),...Array(5).fill('point'),...Array(2).fill('roads'),...Array(2).fill('plenty'),...Array(2).fill('monopoly')]);
 const coast=s.edges.filter(e=>s.vertices[e.a].tiles.filter(id=>s.vertices[e.b].tiles.includes(id)).length===1).sort((a,b)=>{const mid=e=>({x:(s.vertices[e.a].x+s.vertices[e.b].x)/2,y:(s.vertices[e.a].y+s.vertices[e.b].y)/2}),aa=mid(a),bb=mid(b);return Math.atan2(aa.y-302,aa.x-390)-Math.atan2(bb.y-302,bb.x-390);});
 const portTypes=shuffle(s,['any','wood','any','brick','sheep','any','wheat','any','ore']),offset=Math.floor(random(s)*coast.length);for(let i=0;i<9;i++){const e=coast[(offset+Math.floor(i*coast.length/9))%coast.length];s.ports.push({a:e.a,b:e.b,type:portTypes[i]});}
 s.startPlayer=Number.isInteger(options.startPlayer)&&options.startPlayer>=0&&options.startPlayer<playerCount?options.startPlayer:Math.floor(random(s)*playerCount);const first=Array.from({length:playerCount},(_,i)=>(s.startPlayer+i)%playerCount);s.setupOrder=[...first,...[...first].reverse()];s.current=s.startPlayer;
 log(s,`${s.players[s.startPlayer].name}先手。每人依次选择初始村庄和道路，再逆序放置第二组`,s.startPlayer,'start');return s;
}
export function tradeRatio(s,p,res){let ratio=4;for(const port of s.ports){if(s.vertices[port.a].owner!==p&&s.vertices[port.b].owner!==p)continue;if(port.type==='any')ratio=Math.min(ratio,3);else if(port.type===res)ratio=2;}return ratio;}
export function mayTrade(s,p=s.current){return s.current===p&&s.phase==='build'&&s.tradeOpen&&!s.offer;}
export function mayPlayDev(s,p=s.current){return s.current===p&&['roll','build'].includes(s.phase)&&!s.playedDev&&!s.offer;}
export const tradeRecipient=o=>o?.proposedBy===o?.from?o?.with:o?.from;
function validPackage(pack){return pack&&typeof pack==='object'&&!Array.isArray(pack)&&Object.keys(pack).every(r=>RES.includes(r))&&RES.every(r=>Number.isInteger(pack[r]??0)&&(pack[r]??0)>=0&&(pack[r]??0)<=19);}
function validDeal(give,get){return validPackage(give)&&validPackage(get)&&sumPackage(give)>0&&sumPackage(get)>0&&RES.every(r=>!((give[r]??0)>0&&(get[r]??0)>0));}
function dealDescription(give,get){const text=pack=>RES.filter(r=>pack[r]).map(r=>`${pack[r]}${LABEL[r]}`).join(' + ');return `${text(give)} 换 ${text(get)}`;}
function finishEffect(s){s.phase=s.returnPhase??'build';s.returnPhase=null;s.freeRoads=0;s.pendingVictims=[];checkWinner(s);}
function steal(s,p,victim){const bag=RES.flatMap(r=>Array(s.players[victim].resources[r]).fill(r));if(!bag.length){log(s,`${s.players[victim].name}没有资源，强盗空手而归`,p,'robber');return;}const r=bag[Math.floor(random(s)*bag.length)];s.players[victim].resources[r]--;s.players[p].resources[r]++;log(s,`${s.players[p].name}从${s.players[victim].name}手中随机拿走 1 张资源`,p,'robber');}
export function distributeProduction(s,sum){const need=s.players.map(()=>emptyResources());s.production=[];for(const t of s.tiles){if(t.id===s.robber||t.number!==sum||t.type==='desert')continue;for(const id of t.vertices){const v=s.vertices[id];if(v.owner!==null)need[v.owner][t.type]+=v.level;}}
 for(const r of RES){const receivers=need.map((cards,p)=>({p,n:cards[r]})).filter(x=>x.n>0),wanted=receivers.reduce((n,x)=>n+x.n,0),stock=s.bank[r];if(wanted>stock&&receivers.length>1){log(s,`银行${LABEL[r]}不足，多位居民本次均未获得该资源`,s.current,'shortage');continue;}for(const{p,n}of receivers){const amount=Math.min(n,s.bank[r]);if(amount){take(s,p,{[r]:amount});s.production.push({player:p,res:r,n:amount});}}if(wanted>stock&&receivers.length===1)log(s,`银行${LABEL[r]}不足，只发放剩余库存`,receivers[0].p,'shortage');}
 for(const p of s.players){const gains=s.production.filter(x=>x.player===p.id);if(gains.length)log(s,`${p.name}收获 ${gains.map(x=>`${LABEL[x.res]} +${x.n}`).join('、')}`,p.id,'gain');}}
function roll(s){s.dice=[1+Math.floor(random(s)*6),1+Math.floor(random(s)*6)];s.production=[];const sum=s.dice[0]+s.dice[1];log(s,`${s.players[s.current].name}掷出 ${sum} 点`,s.current,'dice');if(sum===7){s.discardRequired=s.players.map(p=>total(p)>7?Math.floor(total(p)/2):0);s.discardLeft=s.discardRequired[0];s.returnPhase='build';s.phase=s.discardRequired.some(n=>n>0)?'discard':'robber';return;}distributeProduction(s,sum);s.phase='build';}
function closeTradingAfterBuild(s){if(!s.options.combinedTradeBuild)s.tradeOpen=false;}
export function applyAction(s,p,a){
 if(!s.players[p])return fail('无效的玩家');if(s.phase==='over')return fail('本局已结束，可以开始新的对局');const player=s.players[p];
 if(a.type==='discard'){const n=s.discardRequired[p]??0;if(s.phase!=='discard'||!n)return fail('现在无需弃牌');const cards=a.resources??{};if(!validPackage(cards)||sumPackage(cards)!==n||!canPay(player,cards))return fail(`请选择 ${n} 张你持有的资源`);pay(s,p,cards);s.discardRequired[p]=0;s.discardLeft=s.discardRequired[0];log(s,`${player.name}弃置 ${n} 张资源`,p,'discard');if(!s.discardRequired.some(x=>x>0))s.phase='robber';return{ok:true};}
 if(['respond','counter','cancelOffer'].includes(a.type)){const o=s.offer;if(!o)return fail('这笔交易已经结束');if(a.type==='cancelOffer'){if(p!==o.proposedBy&&p!==s.current)return fail('你不能取消这笔报价');s.offer=null;log(s,`${player.name}撤回了交易报价`,p,'trade-cancelled');return{ok:true};}if(p!==tradeRecipient(o))return fail('请等待对方回应');
  if(a.type==='counter'){if(!validDeal(a.give,a.get))return fail('双方均需给出资源，同种资源不能出现在交换的两侧');if(!canPay(player,p===o.from?a.give:a.get))return fail('你没有足够的资源支付这个还价');s.offer={...o,give:clone(a.give),get:clone(a.get),proposedBy:p,id:s.eventId++};log(s,`${player.name}提出还价：${dealDescription(a.give,a.get)}`,p,'trade-counter');return{ok:true};}
  if(a.accept!==true){s.offer=null;log(s,`${player.name}拒绝了这笔交易`,p,'trade-declined');return{ok:true,accepted:false};}if(!canPay(s.players[o.from],o.give)||!canPay(s.players[o.with],o.get))return fail('当前持有资源不足，无法完成这笔交易');for(const r of RES){const delta=(o.get[r]??0)-(o.give[r]??0);s.players[o.from].resources[r]+=delta;s.players[o.with].resources[r]-=delta;}log(s,`${s.players[o.from].name}与${s.players[o.with].name}成交：${dealDescription(o.give,o.get)}`,p,'trade');s.offer=null;return{ok:true,accepted:true};
 }
 if(s.current!==p)return fail('请等待其他玩家完成回合');if(s.offer)return fail('请先处理或撤回当前交易报价');
 if(isSetup(s)){if(s.phase==='setup-settlement'){if(a.type!=='settlement')return fail('请先选择并确认初始村庄的位置');if(!legalSettlements(s,p,true).includes(a.id))return fail('村庄之间至少相隔两条边，请选择高亮交点');const v=s.vertices[a.id];v.owner=p;v.level=1;s.setupVertex=v.id;s.phase='setup-road';const second=s.setupIndex>=s.players.length;log(s,`${player.name}放置了第 ${second?2:1} 座初始村庄`,p,'setup');if(second){const cards=emptyResources();for(const tid of v.tiles){const t=s.tiles[tid];if(t.type!=='desert')cards[t.type]++;}take(s,p,cards);if(sumPackage(cards))log(s,`${player.name}获得起始资源：${RES.filter(r=>cards[r]).map(r=>`${LABEL[r]} +${cards[r]}`).join('、')}`,p,'gain');}return{ok:true};}
  if(a.type!=='road'||!legalSetupRoads(s,p).includes(a.id))return fail('初始道路必须紧邻刚放置的村庄');s.edges[a.id].owner=p;s.setupVertex=null;s.setupIndex++;log(s,`${player.name}放置了初始道路`,p,'setup');if(s.setupIndex===s.setupOrder.length){s.current=s.startPlayer;s.phase='roll';updateAwards(s);log(s,`初始布局完成，${s.players[s.current].name}开始第一回合`,s.current,'start');}else{s.current=s.setupOrder[s.setupIndex];s.phase='setup-settlement';}return{ok:true};
 }
 if(a.type==='roll'){if(s.phase!=='roll')return fail('本回合不能再次掷骰');if(checkWinner(s))return{ok:true};roll(s);return{ok:true};}
 if(a.type==='robber'){if(s.phase!=='robber'||!s.tiles[a.tile]||a.tile===s.robber)return fail('请选择强盗当前所在地之外的一块地形');s.robber=a.tile;log(s,`${player.name}将强盗移到${s.tiles[a.tile].type==='desert'?'沙漠':LABEL[s.tiles[a.tile].type]+'产区'}`,p,'robber');s.pendingVictims=[...new Set(s.tiles[a.tile].vertices.map(id=>s.vertices[id].owner).filter(id=>id!==null&&id!==p))];if(s.pendingVictims.length>1)s.phase='victim';else{if(s.pendingVictims.length)steal(s,p,s.pendingVictims[0]);finishEffect(s);}return{ok:true};}
 if(a.type==='victim'){if(s.phase!=='victim'||!s.pendingVictims.includes(a.player))return fail('请选择这块地形相邻的其他玩家');steal(s,p,a.player);finishEffect(s);return{ok:true};}
 if(a.type==='dev'){if(!mayPlayDev(s,p))return fail('发展卡只能在掷骰前或交易建设阶段使用，每回合最多一张');const card=player.dev.find(c=>c.id===a.id);if(!card||card.type==='point')return fail('胜利点牌自动计分，在获胜时公开');if(card.bought===s.turn)return fail('本回合新买的发展卡，下个自己的回合才能使用');const before=s.phase;
  if(card.type==='plenty'){const amount=Math.min(2,sumPackage(s.bank));if(!Array.isArray(a.resources)||a.resources.length!==amount||a.resources.some(r=>!RES.includes(r)))return fail(`请从银行选择 ${amount} 张资源`);const cards=emptyResources();for(const r of a.resources)cards[r]++;if(!RES.every(r=>cards[r]<=s.bank[r]))return fail('银行没有这么多该类资源，请重新选择');}if(card.type==='monopoly'&&!RES.includes(a.resource))return fail('请选择一种资源');
  player.dev=player.dev.filter(c=>c.id!==card.id);s.playedDev=true;s.playedCards.push({type:card.type,player:p});log(s,`${player.name}使用「${DEV_NAMES[card.type]}」`,p,'dev');
  if(card.type==='knight'){player.knights++;updateAwards(s);if(checkWinner(s))return{ok:true};s.returnPhase=before;s.phase='robber';}if(card.type==='roads'){s.returnPhase=before;s.freeRoads=2;s.phase='road-building';if(!legalRoads(s,p).length)finishEffect(s);}if(card.type==='plenty'){const cards=emptyResources();for(const r of a.resources)cards[r]++;take(s,p,cards);}if(card.type==='monopoly')for(const other of s.players){if(other.id===p)continue;player.resources[a.resource]+=other.resources[a.resource];other.resources[a.resource]=0;}checkWinner(s);return{ok:true};
 }
 if(s.phase==='road-building'){if(a.type!=='road'||!legalRoads(s,p).includes(a.id))return fail('请连续完成道路建设卡的免费道路');s.edges[a.id].owner=p;s.freeRoads--;log(s,`${player.name}免费修建了一段道路`,p,'build');updateAwards(s);if(checkWinner(s))return{ok:true};if(!s.freeRoads||!legalRoads(s,p).length)finishEffect(s);return{ok:true};}
 if(s.phase!=='build')return fail('请先完成掷骰或当前事件');
 if(a.type==='end'){s.current=(p+1)%s.players.length;s.turn++;s.phase='roll';s.dice=null;s.playedDev=false;s.tradeOpen=true;s.production=[];s.returnPhase=null;checkWinner(s);return{ok:true};}
 if(['road','settlement','city'].includes(a.type)){const legal=a.type==='road'?legalRoads(s,p):a.type==='city'?legalCities(s,p):legalSettlements(s,p);if(!legal.includes(a.id))return fail('这里不能建设，请选择高亮位置');if(!canPay(player,COST[a.type]))return fail('建设资源不足');pay(s,p,COST[a.type]);if(a.type==='road')s.edges[a.id].owner=p;else{s.vertices[a.id].owner=p;s.vertices[a.id].level=a.type==='city'?2:1;}closeTradingAfterBuild(s);log(s,`${player.name}${a.type==='road'?'修建了一段道路':a.type==='city'?'将村庄升级为城市':'建立了一座村庄'}`,p,'build');updateAwards(s);checkWinner(s);return{ok:true};}
 if(a.type==='bank'){if(!mayTrade(s,p))return fail('本回合的交易阶段已经结束');const units=a.units??1;if(!RES.includes(a.give)||!RES.includes(a.get)||a.give===a.get||!Number.isInteger(units)||units<1||units>19)return fail('请选择不同资源和有效的兑换数量');const cost=tradeRatio(s,p,a.give)*units;if(player.resources[a.give]<cost)return fail(`需要 ${cost} 张${LABEL[a.give]}`);if(s.bank[a.get]<units)return fail(`银行${LABEL[a.get]}仅剩 ${s.bank[a.get]} 张`);pay(s,p,{[a.give]:cost});take(s,p,{[a.get]:units});log(s,`${player.name}向银行用 ${cost}${LABEL[a.give]}换取 ${units}${LABEL[a.get]}`,p,'trade');return{ok:true};}
 if(a.type==='offer'){if(!mayTrade(s,p)||!s.players[a.with]||a.with===p)return fail('请选择当前可交易的其他玩家');if(!validDeal(a.give,a.get))return fail('双方均需提供资源，同种资源不能同时出现在两侧');if(!canPay(player,a.give))return fail('你没有足够的资源支付这个报价');s.offer={from:p,with:a.with,give:clone(a.give),get:clone(a.get),proposedBy:p,id:s.eventId++};log(s,`${player.name}向${s.players[a.with].name}报价：${dealDescription(a.give,a.get)}`,p,'trade-offer');return{ok:true};}
 if(a.type==='buyDev'){if(!s.deck.length)return fail('发展卡已售完');if(!canPay(player,COST.dev))return fail('需要 1 羊毛、1 麦穗和 1 矿石');pay(s,p,COST.dev);const type=s.deck.pop();player.dev.push({type,bought:s.turn,id:s.eventId++});closeTradingAfterBuild(s);log(s,`${player.name}购买了一张发展卡`,p,'dev');checkWinner(s);return{ok:true,card:type};}
 return fail('无法执行这个操作');
}
// The policy only receives this projection: no opponent hand composition,
// unplayed card identity, deck order, random seed or random generator state.
export function observe(s,p){const view={};for(const key of ['version','options','tiles','vertices','edges','ports','bank','playedCards','current','startPlayer','setupOrder','setupIndex','setupVertex','turn','phase','returnPhase','tradeOpen','dice','robber','winner','longestOwner','largestOwner','longest','logs','eventId','production','freeRoads','playedDev','discardRequired','pendingVictims','offer'])view[key]=clone(s[key]);view.me=p;view.deckCount=s.deck.length;view.players=s.players.map(player=>({id:player.id,name:player.name,color:player.color,letter:player.letter,knights:player.knights,resourceCount:total(player),devCount:player.dev.length,publicScore:publicPoints(s,player.id),...(player.id===p?{resources:clone(player.resources),dev:clone(player.dev)}:{})}));return view;}
export function nextAiPlayer(s){if(s.phase==='over')return null;if(s.phase==='discard'){const id=s.discardRequired.findIndex((n,i)=>i>0&&n>0);return id>0?id:null;}if(s.offer){const id=tradeRecipient(s.offer);return id>0?id:null;}return s.current>0?s.current:null;}
export function conservation(s){return RES.every(r=>Number.isInteger(s.bank[r])&&s.bank[r]>=0&&s.bank[r]+s.players.reduce((n,p)=>n+p.resources[r],0)===19);}

// The recipient checks only their own hand; a generic decline reveals no reason to the proposer.
export function declineUnpayableOffer(s,p){const o=s.offer;if(!o||tradeRecipient(o)!==p||!s.players[p])return false;const payment=o.from===p?o.give:o.get;if(canPay(s.players[p],payment))return false;return applyAction(s,p,{type:'respond',accept:false}).ok;}
